/**
 * Notification Types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`). The list
 * envelope and the unread-count payload are the two documented schemas, and the
 * list query is the documented `page`/`limit`/`unreadOnly` surface.
 */

import type { components, paths } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities ─── */

export type NotificationWire = Schemas["NotificationResponseDto"]
export type RecipientType = NotificationWire["recipientType"]
export type NotificationType = NotificationWire["type"]

export type Notification = NotificationWire

/* ─── Query (derived from OpenAPI) ─── */

export type NotificationListQuery = NonNullable<
  paths["/api/v1/dashboard/comms/notifications"]["get"]["parameters"]["query"]
>

/* ─── Response ─── */

export type NotificationList = Schemas["PaginatedNotificationsResponseDto"]
export type UnreadCount = Schemas["UnreadNotificationCountResponseDto"]
